def is_plain_name(name: str) -> bool:
    """True when name is a single relative path component that stays inside a directory."""
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../secret.txt") == False
    ex is_plain_name("/etc/passwd") == False
    if name == "" or name == "." or name == "..":
        return False
    if "/" in name or "\\" in name:
        return False
    return True

def first_readable(names: list[str]) -> str uses fs:
    """Text of the first name in names that can be read from the notes directory, or "" if none can.
    Names are untrusted: only plain names are opened inside notes, and a missing or unreadable file is skipped."""
    post out.byte_len() >= 0
    with fs = fs.sub("notes"):
        for name in names:
            if not is_plain_name(name):
                continue
            content: str | None = fs.read_text(name) else None
            if content is not None:
                return content
    return ""
